import {
  FlatList,
  Pressable,
  RefreshControl,
  useWindowDimensions,
  View,
  TextInput,
} from 'react-native';
import {GroupTaskList} from '../../../board/store/interface';
import TextCM from '../../../../components/Text';
import {
  Dispatch,
  SetStateAction,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {IATTR} from '../../helper';
import {useBoardService} from '../../../../../hooks/apiHooks/useAPI';
import {ITaskDetail} from './helper';
import {Color, Font, NavigationName} from '../../../../../constants';
import {Icon} from '@ui-kitten/components';
import DraggableFlatList, {
  ScaleDecorator,
} from 'react-native-draggable-flatlist';
import {GestureHandlerRootView} from 'react-native-gesture-handler';
import ItemTicket from '../item-ticket';
import styles from './styles';
import {
  useFocusEffect,
  useNavigation,
  useRoute,
} from '@react-navigation/native';
import useBoardStore from '../../../board/store';
import ModalFullScreen from '../../../../components/ModalFullScreen';
import AddTaskScreen from './components/add-task';
import {TYPE_SCREEN} from '../../../../../constants/Size';
import {useTranslation} from 'react-i18next';
import Toast from 'react-native-toast-message';
import AddBoard from './components/add-board';

type Props = {
  groupTaskList: GroupTaskList | undefined;
  taskSelectId: string;
  setGroupTaskList: Dispatch<SetStateAction<GroupTaskList[]>>;
};

const TaskDetailItem = ({
  groupTaskList,
  taskSelectId,
  setGroupTaskList,
}: Props) => {
  const {t} = useTranslation();
  const {width} = useWindowDimensions();
  const refInput = useRef<TextInput>(null);
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const attr = useMemo(
    () => groupTaskList?.attr && JSON.parse(groupTaskList.attr),
    [],
  ) as IATTR;

  const [totalItem, setTotalItem] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [openModal, setOpenModal] = useState<'createTask' | 'editTask' | null>(
    null,
  );
  const [page, setPage] = useState(0);
  const [listTask, setListTask] = useState<ITaskDetail[]>([]);

  const BoardServices = useBoardService();
  const {
    isChangeStatusOfListTask,
    setIsChangeStatusOfListTask,
    setGroupTaskList: setGroupTaskListStore,
    groupTaskList: groupTaskListStore,
  } = useBoardStore();

  useEffect(() => {
    if (groupTaskList?.id) {
      getTasks(0);
    }
  }, [isChangeStatusOfListTask]);

  useFocusEffect(
    useCallback(() => {
      if (route.params?.updatedTask) {
        const updatedTask = route.params.updatedTask as ITaskDetail;
        const taskPrevUpdate = listTask?.find(
          task => task.id === updatedTask.id,
        );

        if (taskPrevUpdate && taskPrevUpdate.status !== updatedTask.status) {
          setIsChangeStatusOfListTask(!isChangeStatusOfListTask);
        } else {
          setListTask(
            listTask.map(task =>
              task.id === updatedTask.id
                ? {
                    ...task,
                    ...updatedTask,
                  }
                : task,
            ),
          );
        }

        // Sau khi dùng xong thì xóa để tránh lặp lại
        navigation.setParams({updatedTask: undefined});
      }
    }, [route.params?.updatedTask]),
  );

  const getTasks = async (page: number) => {
    try {
      const params = {
        page: page,
        size: 50,
        sort: 'createdDate,desc',
      };
      const body = {
        listTaskId: groupTaskList?.listTaskId,
        parentId: 0,
        status: [groupTaskList?.id],
        querySelectTemplate: true,
      };
      const data = await BoardServices.searchTask(body, params);
      if (data) {
        if (page === 0) {
          setListTask(data.data);
        } else {
          setListTask([...listTask, ...data.data]);
        }
        setTotalItem(data?.page?.totalRecords);
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
    }
  };

  const onRefresh = () => {
    setIsLoading(true);
    setPage(0);
    getTasks(0);
  };

  const fetchNextPage = () => {
    if (listTask?.length < totalItem) {
      setPage(page + 1);
      getTasks(page + 1);
    }
  };

  const handleAddtask = () => {
    setOpenModal('createTask');
  };

  const handleDragData = (task: any[]) => {
    setListTask(task);
  };

  const handleViewDetail = (task: ITaskDetail) => {
    navigation.navigate(NavigationName.TaskDetailScreen, {
      taskId: task.id,
      type: 'task',
    });
  };

  const handleCreateTask = async (data: any) => {
    try {
      const dataUpdate = {
        ...data,
        status: groupTaskList?.id,
        id: null,
        listTaskId: groupTaskList?.listTaskId,
        description: null,
        // tags: this.formNewTask.controls.tags.value,
        taskIn: null,
        checkListDtoList: [],
        deleteCheckListDtoList: [],
        listAttachmentId: [],
        subTaskDtoList: [],
      };
      const dataResp = await BoardServices.createTask(dataUpdate);
      if (dataResp) {
        setListTask([dataResp, ...listTask]);
        setTotalItem(totalItem + 1);
      }
    } catch (error) {}
  };

  const handleDeleteBoardTask = async (id: string) => {
    const dataResp = await BoardServices.deleteBoardTask(id);
    if (!dataResp) {
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: 'Xóa không thành công',
      });
    } else {
      setGroupTaskList(prev => prev.filter(item => item.id !== id));
      setGroupTaskListStore(groupTaskListStore.filter(item => item.id !== id));
      Toast.show({
        type: 'success',
        text1: 'Thông báo',
        text2: 'Xóa thành công',
      });
    }
  };

  const handleAddBoardTask = async (data: {name: string; color: string}) => {
    const body = {
      name: data?.name,
      listTask: {
        id: taskSelectId,
      },
      attr: JSON.stringify({
        color: data?.color,
        order:
          Math.max(
            ...groupTaskListStore?.map(g => JSON.parse(g.attr || '{}')?.order),
          ) + 1,
        type: 'custom',
        status: 'open',
      }),
      type: 'custom',
    };
    const dataResp = await BoardServices.addGroupTask(body);
    if (dataResp) {
      setGroupTaskList(prev => [...prev, dataResp]);
      setGroupTaskListStore([...groupTaskListStore, dataResp]);
      setOpenModal(null);
    } else {
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: 'Thêm không thành công',
      });
    }
  };

  const handleGetName = () => {
    return groupTaskList?.type !== 'custom'
      ? t(`TK.${groupTaskList?.name}`)
      : groupTaskList?.name;
  };

  return (
    <>
      <GestureHandlerRootView style={{backgroundColor: '#fff'}}>
        <View
          style={{
            width: width > TYPE_SCREEN.mobile ? width / 2 : width,
            flex: 1,
          }}>
          <View
            style={{
              ...styles.ctn,
              backgroundColor: `${attr?.color}1A`,
              flex: listTask.length > 0 ? 1 : 0,
              borderTopColor: attr?.color,
            }}>
            <View
              style={{
                flexDirection: 'row',
                justifyContent: 'space-between',
                alignItems: 'center',
              }}>
              <View style={styles.ctnHeader}>
                {groupTaskList?.type !== 'add' ? (
                  <>
                    <TextCM style={styles.txtName}>{handleGetName()}</TextCM>
                    <View
                      style={{
                        ...styles.ctnNumbTask,
                        backgroundColor: attr?.color,
                      }}>
                      <TextCM style={styles.txtNumbTask}>{totalItem}</TextCM>
                    </View>
                  </>
                ) : (
                  <Pressable
                    style={{
                      flex: 1,
                    }}
                    onPress={() => setOpenModal('editTask')}>
                    <TextCM
                      style={{
                        textAlign: 'center',
                        color: '#fff',
                        fontFamily: Font.InterSemiBold600,
                        fontSize: 16,
                        textTransform: 'uppercase',
                      }}>
                      + thêm trạng thái
                    </TextCM>
                  </Pressable>
                )}
              </View>

              {groupTaskList?.type === 'custom' && (
                <Pressable
                  onPress={() => handleDeleteBoardTask(groupTaskList?.id)}>
                  <Icon
                    fill={attr?.color}
                    name="close"
                    width={20}
                    height={20}
                  />
                </Pressable>
              )}
            </View>

            <DraggableFlatList
              containerStyle={{flex: 1}}
              data={listTask}
              refreshControl={
                <RefreshControl
                  tintColor={'#FCF450'}
                  onRefresh={onRefresh}
                  refreshing={isLoading}
                />
              }
              contentContainerStyle={{rowGap: 10}}
              onEndReachedThreshold={0.5}
              onEndReached={fetchNextPage}
              showsHorizontalScrollIndicator={false}
              showsVerticalScrollIndicator={false}
              keyExtractor={(item, index) => item.id.toString()}
              onDragBegin={index => {
                console.log(index);
              }}
              onDragEnd={({data}) => handleDragData(data)}
              renderItem={({item, drag, isActive}) => (
                <ScaleDecorator activeScale={0.9}>
                  <Pressable
                    onPress={() => handleViewDetail(item)}
                    onLongPress={drag}
                    disabled={isActive}>
                    <ItemTicket itemTask={item} />
                  </Pressable>
                </ScaleDecorator>
              )}
            />

            {groupTaskList?.type !== 'add' &&
              groupTaskList?.type !== 'completed' && (
                <Pressable onPress={handleAddtask} style={styles.ctnAddTask}>
                  <Icon
                    fill={Color.Text}
                    name="plus-circle-outline"
                    width={20}
                    height={20}
                  />
                  <TextCM style={styles.txtAddtask}>Thêm công việc</TextCM>
                </Pressable>
              )}
          </View>
        </View>
      </GestureHandlerRootView>

      <ModalFullScreen
        isVisible={openModal === 'createTask'}
        children={
          <AddTaskScreen
            resourceId={taskSelectId}
            onClose={() => setOpenModal(null)}
            handleSubmitData={handleCreateTask}
          />
        }
      />

      <ModalFullScreen
        isVisible={openModal === 'editTask'}
        children={
          <AddBoard
            onClose={() => setOpenModal(null)}
            handleSubmitData={handleAddBoardTask}
          />
        }
      />
    </>
  );
};
export default TaskDetailItem;
