import {Icon, List, ListItem} from '@ui-kitten/components';
import {PRIORITIES} from '../../../../../board/components/create-new-task/helper';
type Props = {
  onSave: (data: any) => void;
  value: any;
};
const ModalPriority = ({onSave, value}: Props) => {
  const handleSave = (value: any) => {
    onSave({
      priority: value,
    });
  };
  return (
    <List
      data={[
        ...PRIORITIES,
        {
          value: null,
          name: 'delete',
          label: 'Xoá',
          icon: (
            <Icon
              name="close-circle"
              width={22}
              height={22}
              fill={'#00204D47'}
            />
          ),
        },
      ]}
      renderItem={({item}) => (
        <ListItem
          accessoryRight={
            value !== null && value === item.value ? (
              <Icon name="checkmark-outline" width={24} height={24} />
            ) : undefined
          }
          accessoryLeft={item.icon}
          onPress={() => handleSave(item.value)}
          title={item.label}
        />
      )}
    />
  );
};

export default ModalPriority;
